func cgNl(b []byte, i int32) int32 {
	var k int32 = i
	for (k < port.BlobLen(b)) && (port.BlobU8(b, k) != 10) {
		k += 1
	}
	return k
}

func cgTab(b []byte, i int32, lim int32) int32 {
	var k int32 = i
	for (k < lim) && (port.BlobU8(b, k) != 9) {
		k += 1
	}
	return k
}

func TestEveryFixtureDumpIsItsGolden(emonT *testing.T) {
	// Row: file, password, golden. The dump of the file, read in memory, is the golden's
	// bytes (less its line feed): annotations, fields, signatures, outlines, labels,
	// metadata, named destinations, all four targets.
	var f []byte = port.TestFile("pdf/catalog.txt")
	var n int32 = port.BlobLen(f)
	var pos int32 = 0
	var line int32 = 0
	var rows int32 = 0
	var e int32 = 0
	var s0 int32 = 0
	var s1 int32 = 0
	for pos < n {
		line += 1
		e = cgNl(f, pos)
		if (pos < e) && (port.BlobU8(f, pos) != 35) {
			rows += 1
			s0 = cgTab(f, pos, e)
			s1 = cgTab(f, s0+1, e)
			var t *strings.Builder = port.NewText()
			var g []byte = port.TestFileSpan(f, s1+1, e)
			port.AssertEqAt(emonT, cgDump(port.SrcOfBlob(port.TestFileSpan(f, pos, s0)), t), 0, "opened and read", line)
			port.AssertTextSpan(emonT, t, g, 0, port.BlobLen(g)-1, "the golden", line)
		}
		pos = e + 1
	}
	port.AssertThat(emonT, rows >= 12, "the fixtures were read")
}

func cgPut(t *strings.Builder, txt *port.Cells, s int32, n int32) int32 {
	// A run of `txt` as ASCII text: a code point past 126 (or a control) is `{N}`, its number.
	var i int32 = 0
	var c int32 = 0
	for i < n {
		c = port.CellsAt(txt, s+i)
		if (c >= 32) && (c <= 126) {
			port.TextCp(t, c)
		} else {
			port.TextAscii(t, "{")
			port.TextI32(t, c)
			port.TextAscii(t, "}")
		}
		i += 1
	}
	return 0
}

func cgFold(h int32, v int32) int32 {
	// The rolling hash the corpus rows use: h * 131 + v, modulo 8388593 (the same prime as
	// the geometry digest of `kin/pdfdoctest.kin`), v taken modulo it first.
	var x int32 = v % 8388593
	if x < 0 {
		x += 8388593
	}
	return ((h * 131) + x) % 8388593
}

